import { mkdir, rm, writeFile, cp, readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { firm, practices, articles, translations } from '../content.mjs';

await rm('dist', { recursive: true, force: true });
await mkdir('dist/assets', { recursive: true });
await cp('assets', 'dist/assets', { recursive: true, filter: p => !p.endsWith('-original.png') });
for (const f of ['styles.css', 'app.js']) await cp(f, `dist/${f}`);
const version = createHash('sha256').update(await readFile('styles.css')).update(await readFile('app.js')).digest('hex').slice(0, 10);
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const arrow = '<span aria-hidden="true">↗</span>';
const icons = {
  family: '<circle cx="9" cy="7" r="3"/><circle cx="21" cy="7" r="3"/><circle cx="15" cy="18" r="2.5"/><path d="M3 25v-6a6 6 0 0 1 9-5m6 0a6 6 0 0 1 9 5v6M10 28v-3a5 5 0 0 1 10 0v3"/>',
  tree: '<path d="M15 28V17M8 28h14M15 3l-9 9h5l-7 8h22l-7-8h5z"/>',
  home: '<path d="M3 14L15 4l12 10M7 12v15h16V12M12 27v-9h6v9"/>',
  document: '<path d="M8 3h12l5 5v21H5V3zM20 3v6h5M10 15h10M10 20h10M10 25h6"/>',
  briefcase: '<rect x="3" y="10" width="24" height="17" rx="1"/><path d="M10 10V5h10v5M3 17c8 5 16 5 24 0M14 18v5h3v-5"/>',
  building: '<path d="M5 28V9l10-5 10 5v19M2 28h26M10 12h2m6 0h2m-10 5h2m6 0h2M12 28v-6h6v6"/>'
};
const icon = name => `<svg viewBox="0 0 30 32" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const routeNames = {
  home: ['',''], about: ['despre-cabinet','about'], practices: ['arii-de-practica','practice-areas'], booking: ['programari','appointments'], articles: ['articole','insights'], contact: ['contact','contact'], privacy: ['confidentialitate','privacy'], terms: ['termeni','terms'], cookies: ['cookies','cookies'], cancel: ['anulari-si-reprogramari','cancellations'], accessibility: ['accesibilitate','accessibility'], studio: ['administrare','editor']
};
const url = (lang, key, item) => {
  const prefix = lang === 'en' ? '/en/' : '/';
  if (key === 'practice') return prefix + routeNames.practices[lang === 'en' ? 1 : 0] + '/' + (lang === 'en' ? item.enSlug : item.slug) + '/';
  if (key === 'article') return prefix + routeNames.articles[lang === 'en' ? 1 : 0] + '/' + (lang === 'en' ? item.enSlug : item.slug) + '/';
  const slug = routeNames[key][lang === 'en' ? 1 : 0];
  return prefix + (slug ? slug + '/' : '');
};
const button = (href, label, cls = '') => `<a class="button ${cls}" href="${href}">${label}${arrow}</a>`;
const photo = (name, cls='', eager=false, alt='') => {
 const hero=cls==='hero-image',desktop=hero?'hero-desktop':'desktop',mobile=hero?'hero-mobile':'mobile';
 const widths=hero?[640,800]:[640,960,1280],size=hero?'(max-width: 760px) 100vw, 52vw':'(max-width: 760px) 100vw, 50vw';
 const set=(mode,values,format)=>values.map(w=>`/assets/${name}-${mode}-${w}.${format} ${w}w`).join(', ');
 return `<picture class="${cls}"><source media="(max-width: 760px)" type="image/avif" srcset="${set(mobile,[480,720],'avif')}" sizes="100vw"><source media="(max-width: 760px)" type="image/webp" srcset="${set(mobile,[480,720],'webp')}" sizes="100vw"><source type="image/avif" srcset="${set(desktop,widths,'avif')}" sizes="${size}"><img src="/assets/${name}-${desktop}-${widths.at(-1)}.webp" srcset="${set(desktop,widths,'webp')}" sizes="${size}" alt="${esc(alt)}" width="${hero?800:1280}" height="${hero?1000:960}" ${eager?'fetchpriority="high" loading="eager"':'loading="lazy"'} decoding="async"></picture>`;
};
const sectionHead = (kicker, title, text='', extra='') => `<div class="section-head"><div><p class="eyebrow">${kicker}</p><h2>${title}</h2></div><div class="section-aside">${text?`<p>${text}</p>`:''}${extra}</div></div>`;
const practiceCards = lang => `<div class="practice-grid">${practices.map((p,i)=>`<a class="practice-card" href="${url(lang,'practice',p)}">${photo(p.image,'practice-image')}<div class="practice-card-content"><div class="card-top">${icon(p.icon)}<span class="card-index">0${i+1}</span></div><h3>${p[lang].title}</h3><p>${p[lang].short}</p><span class="text-link">${translations[lang].detail}${arrow}</span></div></a>`).join('')}</div>`;
const articleCards = lang => `<div class="article-grid">${articles.map((a,i)=>`<article class="article-card"><a class="article-image image-${i}" href="${url(lang,'article',a)}" aria-label="${esc(a[lang].title)}">${photo(a.image)}</a><p class="eyebrow">${a.category[lang==='en'?1:0]} <span>· ${lang==='ro'?'3 min lectură':'3 min read'}</span></p><h3><a href="${url(lang,'article',a)}">${a[lang].title}</a></h3><p>${a[lang].excerpt}</p><a class="text-link" href="${url(lang,'article',a)}">${translations[lang].read}${arrow}</a></article>`).join('')}</div>`;
const process = lang => `<div class="process-steps">${translations[lang].process.map((p,i)=>`<div><span class="step-number">0${i+1}</span><h3>${p[0]}</h3><p>${p[1]}</p></div>`).join('')}</div>`;
const cta = lang => { const t=translations[lang]; return `<section class="cta"><div class="container cta-inner"><div><p class="eyebrow">${t.ctaKicker}</p><h2>${t.ctaTitle}</h2></div><div><p>${t.ctaText}</p>${button(url(lang,'booking'),t.book,'light')}<a class="cta-phone" href="tel:${firm.phone}">${firm.phoneLabel}</a></div></div></section>`; };
const innerHero = (lang, kicker, title, lead, image=false) => `<section class="inner-hero ${image?'with-image':''}">${image?photo(typeof image==='string'?image:'commercial-v2','inner-image',true):''}<div class="container"><div class="breadcrumb"><a href="${url(lang,'home')}">${translations[lang].nav[0]}</a><span aria-hidden="true">/</span><span>${kicker}</span></div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="lead">${lead}</p></div></section>`;
const header = (lang, key, item) => {
 const t=translations[lang],en=lang==='en',other=en?'ro':'en';
 const accessIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9.2"/><circle cx="12" cy="7" r="1.4"/><path d="M6.8 10.2h10.4M12 10.2v5.2m0-2.3-3.3 5m3.3-5 3.3 5"/></svg>';
 return `<a class="skip" href="#main">${t.skip}</a><div class="intro" aria-hidden="true"><span>MG<span class="intro-line"></span></span></div><header class="header"><div class="nav-wrap"><a class="brand" href="${url(lang,'home')}" aria-label="${t.office} ${firm.name} — ${t.nav[0]}"><span class="monogram">MG</span><span class="brand-text">MANUELA GALUSCAN<small>${t.office}</small></span></a><nav id="navigation" aria-label="${t.navigation}">${['home','about','practices','booking','articles','contact'].map((k,i)=>`<a href="${url(lang,k)}" ${k===key||(key==='practice'&&k==='practices')||(key==='article'&&k==='articles')?'aria-current="page"':''}>${t.nav[i]}</a>`).join('')}</nav><div class="nav-end"><div class="language-control"><a id="language-toggle" class="language-toggle" href="${url(other,key,item)}" hreflang="${other}" aria-label="${en?'Current language English; switch to Romanian':'Limba curentă română; schimbă în engleză'}">${lang.toUpperCase()}</a></div><div class="accessibility-control"><button id="accessibility-toggle" class="accessibility-toggle" aria-expanded="false" aria-controls="accessibility-panel" aria-label="${en?'Display accessibility options':'Opțiuni de accesibilitate'}">${accessIcon}</button><section id="accessibility-panel" class="utility-panel accessibility-panel" aria-labelledby="accessibility-title" hidden><div class="utility-panel-heading"><h2 id="accessibility-title">${t.accessibility}</h2><button id="accessibility-close" aria-label="${en?'Close accessibility options':'Închide opțiunile de accesibilitate'}">×</button></div><p>${en?'Adjust the display to suit your reading preferences.':'Adaptați afișarea la preferințele de lectură.'}</p><span class="setting-label">${en?'Text size':'Dimensiunea textului'}</span><div class="text-size-controls"><button id="text-decrease" aria-label="${en?'Decrease text size':'Micșorează textul'}">A−</button><output id="text-size-label" aria-live="polite">100%</output><button id="text-increase" aria-label="${en?'Increase text size':'Mărește textul'}">A+</button></div><button id="contrast-toggle" class="contrast-toggle" aria-pressed="false">${en?'High contrast':'Contrast ridicat'}<span aria-hidden="true">◐</span></button><button id="accessibility-reset" class="accessibility-reset">${en?'Reset display':'Resetează afișarea'}</button></section></div><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="${t.menu}" data-open="${t.menu}" data-close="${t.close}"><span></span><span></span></button></div></div></header>`;
};
const footer = lang => { const t=translations[lang]; return `<footer class="footer"><div class="container footer-top"><div class="footer-brand"><a class="brand" href="${url(lang,'home')}"><span class="monogram">MG</span><span class="brand-text">MANUELA GALUSCAN<small>${t.office}</small></span></a><p>${t.footerText}</p><span class="footer-location">${t.city}</span></div><div><h2>${t.navigation}</h2><ul>${['about','practices','booking','articles','contact'].map((k,i)=>`<li><a href="${url(lang,k)}">${t.nav[i+1]}</a></li>`).join('')}</ul></div><div><h2>${t.legal}</h2><ul>${['privacy','terms','cookies','cancel','accessibility'].map(k=>`<li><a href="${url(lang,k)}">${t[k]}</a></li>`).join('')}</ul></div><div class="footer-contact"><h2>${t.contact}</h2><a href="tel:${firm.phone}">${firm.phoneLabel}</a><a href="mailto:${firm.email}">${firm.email}</a><p>${lang==='ro'?'Consultații la o dată convenită cu cabinetul.':'Consultations by arrangement with the practice.'}</p></div></div><div class="container footer-notice"><p>${t.disclaimer}</p><p>${t.concept}</p></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} ${firm.name}. ${t.rights}</span><a href="${url(lang,'studio')}">${lang==='ro'?'Atelier editorial · demo':'Editorial studio · demo'}</a><span>Design & web · <a href="https://avyron.eu" target="_blank" rel="noopener noreferrer">AVYRON ${arrow}</a></span></div></footer><a class="back-top" href="#top" aria-label="${lang==='ro'?'Înapoi sus':'Back to top'}">↑</a>`; };

function home(lang) {
 const t=translations[lang],en=lang==='en';
 return `<section class="hero"><div class="container hero-grid"><div class="hero-content"><p class="eyebrow">${t.heroKicker}</p><h1>${t.heroTitle}</h1><p class="hero-copy">${t.heroText}</p><div class="hero-actions">${button(url(lang,'booking'),t.book,'gold')}<a class="hero-link" href="#arii">${t.explore}<span aria-hidden="true">↓</span></a></div><div class="hero-location"><span class="location-dot" aria-hidden="true"></span>${t.city}</div></div><figure class="hero-visual">${photo('consultation-v2','hero-image',true,en?'Illustrative scene of a contemporary legal consultation and document review.':'Scenă ilustrativă: consultație juridică și analiza documentelor.')}<figcaption>${en?'Legal analysis. Direct communication.':'Analiză juridică. Comunicare directă.'}</figcaption></figure></div></section><div class="trust-strip"><div class="container">${t.trust.map((a,i)=>`<div><span class="trust-mark" aria-hidden="true">0${i+1}</span><span>${a}</span></div>`).join('')}</div></div><section id="arii" class="section container practice-section">${sectionHead(t.practiceKicker,t.practiceTitle,t.practiceText)}${practiceCards(lang)}</section><section class="about-section"><div class="container about-grid"><figure class="about-photo">${photo('commercial-v2','',false,en?'Illustrative contemporary setting for legal analysis and consultation.':'Cadru contemporan ilustrativ pentru analiză juridică și consultații.')}<figcaption>${en?'A considered professional framework.':'Un cadru profesional pentru analiză și dialog.'}</figcaption><div class="experience-seal"><strong>27<span>+</span></strong><span>${en?'YEARS IN<br>LEGAL PRACTICE':'ANI DE<br>EXPERIENȚĂ'}</span></div></figure><div class="about-copy"><p class="eyebrow">${t.aboutKicker}</p><h2>${t.aboutTitle}</h2><p>${t.aboutText}</p><p>${t.aboutText2}</p><div class="signature">Manuela Galuscan<small>${t.office}</small></div><a class="text-link" href="${url(lang,'about')}">${t.aboutLink}${arrow}</a></div></div></section><section class="section container process-section">${sectionHead(t.processKicker,t.processTitle)}${process(lang)}</section><section class="insights-section"><div class="container">${sectionHead(t.articleKicker,t.articleTitle,'',`<a class="text-link" href="${url(lang,'articles')}">${t.articleLink}${arrow}</a>`)}${articleCards(lang)}</div></section>${cta(lang)}`;
}
function about(lang) {
 const t=translations[lang], en=lang==='en';
 return `${innerHero(lang,t.nav[1],en?'Professional experience.<br>A rigorous approach.':'Experiență profesională.<br>O abordare riguroasă.',en?'Over 27 years in legal practice. A considered approach to the questions that matter to you.':'Peste 27 de ani în profesia de avocat. O abordare atentă a întrebărilor care contează pentru dumneavoastră.')}<section class="section container about-grid"><div class="about-photo">${photo('commercial-v2','',true)}<div class="experience-seal"><strong>27<span>+</span></strong><span>${en?'YEARS IN<br>LEGAL PRACTICE':'ANI ÎN<br>AVOCATURĂ'}</span></div></div><div class="about-copy"><p class="eyebrow">${firm.name.toUpperCase()}</p><h2>${en?'A relationship built<br>on clear communication.':'O relație construită<br>pe comunicare clară.'}</h2><p>${t.aboutText2}</p><p>${en?'Every matter has its own context. Listening, examining the documents and explaining the available paths form the basis of an informed conversation. The practice works with individuals and businesses in family, inheritance, property, civil, employment and commercial matters.':'Fiecare situație are propriul context. Ascultarea, analiza documentelor și explicarea opțiunilor formează baza unei discuții informate. Cabinetul asistă persoane fizice și societăți în domeniul familiei, succesiunilor, proprietății, dreptului civil, muncii și dreptului comercial.'}</p><div class="signature">Manuela Galuscan</div></div></section><section class="values section"><div class="container">${sectionHead(en?'THE WAY WE WORK':'FELUL ÎN CARE LUCRĂM',en?'Rigour in analysis.<br>Care in communication.':'Rigoare în analiză.<br>Atenție în comunicare.')}<div class="values-grid">${(en?[['Discretion','The first conversation starts with the information necessary to understand your request. Confidential documents are shared through an agreed channel.'],['Clarity','Options, engagement terms and next steps are explained in a way that supports an informed decision.'],['Individual attention','The approach reflects the facts, documents and objectives of your particular situation.']]:[['Discreție','Prima discuție începe cu informațiile necesare înțelegerii solicitării. Documentele confidențiale se transmit printr-un canal convenit.'],['Claritate','Opțiunile, condițiile colaborării și pașii următori sunt explicate pentru a susține o decizie informată.'],['Atenție individuală','Abordarea ține seama de faptele, documentele și obiectivele situației dumneavoastră.']]).map(([h,p],i)=>`<div><span class="step-number">0${i+1}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>${cta(lang)}`;
}
function practice(lang,p) {
 const t=translations[lang], d=p[lang], en=lang==='en';
 return `${innerHero(lang,t.nav[2],d.title,d.lead,p.image)}<section class="section container detail-layout"><div class="detail-content"><p class="eyebrow">${en?'AN INDIVIDUAL APPROACH':'O ABORDARE ADAPTATĂ'}</p><h2>${t.included}</h2><p class="large-text">${d.body}</p><p class="national-note">${en?'Legal assistance and representation are available to clients throughout Romania, on terms agreed for each matter.':'Cabinetul poate asista și reprezenta clienți din întreaga Românie, în condițiile stabilite pentru fiecare cauză.'}</p><ul class="service-list">${d.services.map(s=>`<li>${s}</li>`).join('')}</ul><div class="preparation"><h3>${t.prepare}</h3><p>${d.prepare}</p></div><p class="fineprint">${en?'The information is general. The assessment of your situation and any engagement terms are agreed directly with the practice.':'Informațiile sunt generale. Evaluarea situației și condițiile unei eventuale colaborări se stabilesc direct cu cabinetul.'}</p></div><aside class="detail-sidebar"><p class="eyebrow">${en?'LET’S TALK':'SĂ DISCUTĂM'}</p><h2>${en?'An individual<br>legal assessment.':'O evaluare juridică<br>individualizată.'}</h2><p>${en?'Arrange an initial conversation with the practice.':'Stabiliți o primă discuție cu cabinetul.'}</p>${button(url(lang,'booking'),t.book)}<a class="sidebar-phone" href="tel:${firm.phone}">${firm.phoneLabel}</a><hr><h3>${t.related}</h3>${practices.filter(a=>a!==p).map(a=>`<a class="sidebar-link" href="${url(lang,'practice',a)}">${a[lang].title}${arrow}</a>`).join('')}</aside></section>${cta(lang)}`;
}
function booking(lang) {
 const en=lang==='en',t=translations[lang];
 return `${innerHero(lang,t.nav[3],en?'Time for your<br><em>important questions.</em>':'Timp pentru întrebările<br><em>importante.</em>',en?'Explore the consultation journey, from choosing a format to reviewing your appointment.':'Descoperiți parcursul unei consultații, de la alegerea formatului la verificarea programării.')}<section class="section container booking-layout"><div><div class="demo-note"><span class="status-dot"></span><div><strong>${en?'Interactive presentation':'Prezentare interactivă'}</strong><p>${en?'Dates and time slots are illustrative. No real appointment or payment is made and no personal details are collected. Fees and cancellation terms will be set by the practice.':'Datele și intervalele sunt ilustrative. Nu se efectuează rezervări sau plăți și nu se colectează date personale. Onorariile și condițiile de anulare vor fi stabilite de cabinet.'}</p></div></div><ol class="booking-progress"><li aria-current="step"><span>1</span>${en?'Format':'Format'}</li><li><span>2</span>${en?'Date & time':'Dată și oră'}</li><li><span>3</span>${en?'Review':'Verificare'}</li></ol><div class="booking-panel" data-booking><fieldset class="format-fields"><legend>${en?'How would you like to meet?':'Cum doriți să discutăm?'}</legend><div class="format-options"><label><input type="radio" name="format" value="online" checked><span><strong>${en?'Online consultation':'Consultație online'}</strong><small>${en?'A conversation from wherever you are':'O discuție, de oriunde vă aflați'}</small></span><span aria-hidden="true">↗</span></label><label><input type="radio" name="format" value="office"><span><strong>${en?'At the practice':'La cabinet'}</strong><small>${en?'Bucharest · location agreed directly':'București · locație stabilită direct'}</small></span><span aria-hidden="true">⌂</span></label></div></fieldset><fieldset class="duration-fields"><legend>${en?'Illustrative duration':'Durată ilustrativă'}</legend><label><input type="radio" name="duration" value="30" checked>30 ${en?'minutes':'minute'}</label><label><input type="radio" name="duration" value="60">60 ${en?'minutes':'minute'}</label></fieldset><div class="calendar-header"><h2 id="calendar-month"></h2><div><button class="calendar-arrow" data-calendar-prev aria-label="${en?'Previous month':'Luna anterioară'}">←</button><button class="calendar-arrow" data-calendar-next aria-label="${en?'Next month':'Luna următoare'}">→</button></div></div><p class="fineprint">${en?'Example calendar · Europe/Bucharest timezone':'Calendar exemplificativ · Fus orar Europe/Bucharest'}</p><div class="calendar-week" aria-hidden="true">${(en?['Mo','Tu','We','Th','Fr','Sa','Su']:['Lu','Ma','Mi','Jo','Vi','Sâ','Du']).map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-days" id="calendar-days" role="group" aria-label="${en?'Choose an illustrative date':'Alegeți o dată ilustrativă'}"></div><fieldset class="time-fields"><legend>${en?'Illustrative time slots':'Intervale ilustrative'}</legend><div id="time-slots"><p class="fineprint">${en?'Choose a date to see example times.':'Alegeți o dată pentru a vedea exemple de intervale.'}</p></div></fieldset></div></div><aside class="booking-summary"><p class="eyebrow">${en?'CONSULTATION SUMMARY':'SUMARUL CONSULTAȚIEI'}</p><h2>${en?'Space for<br>clarity.':'Spațiu pentru<br>claritate.'}</h2><dl><div><dt>${en?'Format':'Format'}</dt><dd id="summary-format">${en?'Online consultation':'Consultație online'}</dd></div><div><dt>${en?'Duration':'Durată'}</dt><dd id="summary-duration">30 min</dd></div><div><dt>${en?'Date & time':'Dată și oră'}</dt><dd id="summary-date">${en?'Not selected':'Neselectate'}</dd></div><div><dt>${en?'Fee':'Onorariu'}</dt><dd>${en?'To be set by the practice':'Va fi stabilit de cabinet'}</dd></div></dl><p class="fineprint">${en?'Payment will only be available after the fee, provider and cancellation terms are configured and approved.':'Plata va fi disponibilă după configurarea și aprobarea onorariului, a procesatorului și a condițiilor de anulare.'}</p><a class="text-link" href="${url(lang,'cancel')}">${t.cancel}${arrow}</a><button class="button gold" id="review-booking" disabled>${en?'Review demo selection':'Verificați selecția demo'}${arrow}</button><p id="booking-result" role="status" aria-live="polite"></p><hr><p>${en?'For an actual consultation:':'Pentru o consultație reală:'}</p><a href="tel:${firm.phone}" class="sidebar-phone">${firm.phoneLabel}</a><a class="text-link" href="${url(lang,'contact')}">${t.contact}${arrow}</a></aside></section><section class="container faq-section"><p class="eyebrow">${en?'USEFUL TO KNOW':'UTIL DE ȘTIUT'}</p><h2>${en?'Before the consultation':'Înainte de consultație'}</h2>${(en?[['Is this an actual booking?','This version demonstrates the journey. No slot is reserved and no payment is processed. Contact the practice to arrange an actual consultation.'],['How will I receive a confirmation?','In the operational version, confirmation will follow a verified payment and calendar reservation. An onscreen selection alone will not constitute confirmation.'],['Can I share documents here?','No confidential documents are requested in this presentation. Agree a suitable transfer channel directly with the practice.'],['Is consultation in English available?','The website is bilingual. Please confirm the language of the consultation with the practice when arranging the meeting.']]:[['Aceasta este o programare reală?','Această versiune demonstrează parcursul. Nu rezervă intervale și nu procesează plăți. Pentru o consultație reală, contactați cabinetul.'],['Cum voi primi confirmarea?','În versiunea operațională, confirmarea va urma verificarea plății și rezervarea în calendar. Simpla selectare a unui interval nu va reprezenta confirmarea programării.'],['Pot transmite documente aici?','Această prezentare nu solicită documente confidențiale. Stabiliți direct cu cabinetul un canal potrivit pentru transmitere.'],['Consultația se poate desfășura în engleză?','Site-ul este bilingv. Limba consultației se confirmă direct cu cabinetul la stabilirea întâlnirii.']]).map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</section>`;
}
function contact(lang) {
 const en=lang==='en',t=translations[lang];
 return `${innerHero(lang,t.contact,en?'Contact and<br><em>legal consultations.</em>':'Contact și<br><em>consultații juridice.</em>',en?'Contact the practice to arrange a consultation or clarify the appropriate next step.':'Contactați cabinetul pentru stabilirea unei consultații sau pentru clarificarea următorului pas.')}<section class="section container contact-layout"><div><p class="eyebrow">${t.office.toUpperCase()}</p><h2>${firm.name}</h2><div class="contact-items"><div><span>01</span><div><h3>${en?'Telephone':'Telefon'}</h3><a href="tel:${firm.phone}">${firm.phoneLabel}</a></div></div><div><span>02</span><div><h3>Email</h3><a href="mailto:${firm.email}">${firm.email}</a></div></div><div><span>03</span><div><h3>${en?'Location':'Localizare'}</h3><p>${t.city}</p><small>${en?'Clients can be represented throughout Romania. Meeting arrangements are agreed directly.':'Cabinetul poate reprezenta clienți din întreaga țară. Detaliile întâlnirii se stabilesc direct.'}</small></div></div></div><p class="fineprint">${en?'Please do not send identification documents, information about children, health data or details of a case in your initial message. Agree a suitable channel with the practice.':'Vă rugăm să nu transmiteți acte de identitate, informații despre minori, date medicale sau detalii ale unui dosar în mesajul inițial. Conveniți un canal potrivit cu cabinetul.'}</p></div><div class="contact-box"><p class="eyebrow">${en?'THE FIRST STEP':'PRIMUL PAS'}</p><h2>${en?'What would you<br>like to clarify?':'Ce doriți<br>să clarificați?'}</h2><p>${en?'For this presentation, contact is available by phone or email. A public message form will be enabled only after its data handling and delivery settings are approved.':'Pentru această prezentare, contactul este disponibil prin telefon sau e-mail. Formularul public va fi activat după aprobarea modului de prelucrare și transmitere a datelor.'}</p>${button(`mailto:${firm.email}`,en?'Write to the practice':'Scrieți cabinetului','gold')}${button(url(lang,'booking'),en?'Explore online appointments':'Descoperiți programările online','outline')}<div class="contact-footnote">${icon('document')}<p>${en?'Please flag any approaching deadline directly by phone. A website visit or email does not suspend legal deadlines.':'Semnalați telefonic orice termen apropiat. Vizitarea site-ului sau trimiterea unui e-mail nu suspendă termenele legale.'}</p></div></div></section>`;
}
const legalContent = {
 privacy: {
  ro: [['Despre această pagină','Model pregătit pentru validarea cabinetului înaintea activării funcțiilor care colectează date. Denumirea profesională completă, sediul, datele de identificare și rolurile furnizorilor trebuie confirmate de cabinet. Această pagină nu certifică o conformitate GDPR completă.'],['Ce se întâmplă în această demonstrație','Nu există formular de contact funcțional, conturi de client, încărcare de documente sau plăți. Selecțiile din calendar rămân în memoria paginii și dispar la reîncărcare. Atelierul editorial salvează opțional numai conținut demonstrativ în browserul utilizatorului, dacă acesta alege salvarea.'],['Date tehnice și găzduire','Furnizorii de găzduire și infrastructură pot prelucra date tehnice precum adresa IP și informații despre cerere, pentru livrarea și protejarea site-ului. Configurația, destinatarii, localizarea prelucrării, eventualele transferuri și perioadele de păstrare trebuie documentate înaintea lansării serviciului final.'],['Contactul prin telefon sau e-mail','Dacă alegeți aceste canale, furnizorul dumneavoastră de telefonie sau e-mail și furnizorul destinatarului prelucrează date potrivit propriilor condiții. Limitați mesajul inițial la datele de contact și o descriere generală. Nu transmiteți detalii sensibile până la convenirea canalului de lucru.'],['Pentru versiunea operațională','Cabinetul va defini separat scopurile și temeiurile pentru solicitări, programări, contractare și evidențe financiar-contabile, destinatarii, termenele de păstrare și măsurile de securitate. Consimțământul pentru marketing, dacă va exista, va fi opțional și separat. Nu vor fi solicitate date de card prin site.'],['Drepturi și solicitări','În condițiile aplicabile, persoanele vizate pot solicita accesul, rectificarea, ștergerea, restricționarea sau portabilitatea și se pot opune prelucrării. Consimțământul poate fi retras pentru prelucrările bazate pe acesta. Pot fi adresate solicitări cabinetului la adresa de e-mail publicată și plângeri autorității de supraveghere competente, în România ANSPDCP.']],
  en: [['About this notice','A draft for the practice to validate before data collection features are activated. The full professional name, address, identification details and provider roles must be confirmed. This page does not certify complete GDPR compliance.'],['What this demonstration does','There is no operational contact form, client account, document upload or payment facility. Calendar selections remain in page memory and disappear on reload. The editorial studio optionally stores demonstration content in the user’s browser when the user chooses to save it.'],['Technical data and hosting','Hosting and infrastructure providers may process technical data, such as IP addresses and request information, to deliver and protect the website. Configuration, recipients, processing locations, transfers and retention must be documented before the final service launches.'],['Phone and email contact','If you choose these channels, your telephone or email provider and the recipient’s provider process data under their own terms. Keep the initial message to contact information and a general description. Do not send sensitive details before agreeing a suitable channel.'],['The operational version','The practice will define the purposes and legal bases for enquiries, appointments, engagement and accounting, as well as recipients, retention and security measures. Any marketing consent will be optional and separate. Card details will not be requested through this website.'],['Rights and requests','Subject to applicable conditions, individuals may request access, correction, erasure, restriction or portability, and object to processing. Consent can be withdrawn for consent-based processing. Requests may be sent to the practice at its published email address and complaints to the competent supervisory authority, in Romania ANSPDCP.']]
 },
 terms: {
  ro: [['Statutul prezentării','Acest website este un concept vizual realizat pentru evaluarea cabinetului Manuela Galuscan. Conținutul profesional și datele de identificare sunt supuse confirmării cabinetului înaintea utilizării ca serviciu operațional. Imaginile ambientale sunt create cu AI și nu reprezintă sediul sau instanțe asociate cabinetului.'],['Informații generale','Textele și materialele sunt informative. Ele nu reprezintă opinii juridice pentru o situație individuală și nu trebuie utilizate ca substitut al unei consultații. Nu sunt promise rezultate sau soluții garantate.'],['Relația profesională','Trimiterea unui mesaj, selectarea unui interval demonstrativ sau consultarea site-ului nu creează prin sine o relație avocat–client. Preluarea unei cauze, verificările necesare și condițiile colaborării se stabilesc direct cu cabinetul.'],['Programări și onorarii','Modulul de programări este demonstrativ. Nu există rezervare în calendar, plată sau confirmare automată. Înaintea activării vor fi stabilite și afișate durata, onorariul total aplicabil, condițiile contractuale și politicile de anulare.'],['Utilizarea site-ului','Utilizați site-ul în mod legal și fără a afecta disponibilitatea, securitatea sau drepturile altor persoane. Textele și identitatea cabinetului nu pot fi reutilizate într-un mod care ar crea o asociere neautorizată.'],['Limba conținutului','Versiunea în limba engleză facilitează accesul la prezentare. Limba serviciilor și a documentelor profesionale se stabilește direct cu cabinetul.']],
  en: [['Status of this presentation','This website is a visual concept prepared for review by Manuela Galuscan’s practice. Professional content and identification details require confirmation before operational use. Atmospheric images are AI-generated and do not depict the actual practice or associated courts.'],['General information','Texts and materials are informative. They are not legal opinions on individual circumstances and should not replace a consultation. No result or guaranteed solution is promised.'],['Professional engagement','Sending a message, selecting an illustrative slot or browsing the website does not itself create a lawyer–client relationship. Acceptance of a matter, necessary checks and engagement terms are agreed directly with the practice.'],['Appointments and fees','The booking module is a demonstration. No calendar reservation, payment or automatic confirmation occurs. Duration, the applicable total fee, engagement terms and cancellation policies will be set and displayed before activation.'],['Website use','Use the website lawfully without affecting availability, security or other people’s rights. The practice’s identity and texts must not be reused in a way that suggests an unauthorised association.'],['Content language','The English version facilitates access to this presentation. The language of services and professional documents is agreed directly with the practice.']]
 },
 cookies: {
  ro: [['Configurația actuală','Codul acestei prezentări nu setează cookies proprii și nu încarcă instrumente de analiză, pixeli de marketing, hărți sau videoclipuri terțe. Fonturile și imaginile sunt livrate local.'],['Stocare în browser','Preferințele de accesibilitate (dimensiunea textului și contrastul) sunt păstrate în localStorage pentru continuitatea afișării și pot fi șterse prin resetarea opțiunilor. Calendarul demonstrativ utilizează numai memoria paginii. În atelierul editorial, butonul de salvare poate crea o copie locală a textelor demonstrative în localStorage, pe dispozitivul utilizatorului. Aceasta poate fi ștearsă prin butonul dedicat sau din setările browserului. Nu introduceți date despre clienți sau dosare.'],['Infrastructură','Pe adresa publică Sites a fost observat cookie-ul tehnic Cloudflare __cf_bm, utilizat pentru protecția împotriva traficului automatizat. Conform documentației furnizorului, acesta expiră după 30 de minute de inactivitate continuă. Configurația și comportamentul pe domeniul final trebuie reverificate înaintea lansării operaționale.'],['Modificări ulterioare','Dacă vor fi introduse funcții neesențiale care folosesc cookies sau tehnologii similare, acestea vor fi inventariate și gestionate prin opțiuni adecvate înainte de activare.']],
  en: [['Current configuration','This presentation’s code does not set first-party cookies or load analytics, marketing pixels, third-party maps or embedded videos. Fonts and images are served locally.'],['Browser storage','Accessibility preferences (text size and contrast) are stored in localStorage for display continuity and can be cleared by resetting the options. The sample calendar uses page memory only. In the editorial studio, choosing to save can create a local copy of demonstration texts in localStorage on the user’s device. It can be removed using the dedicated button or browser settings. Do not enter client or case information.'],['Infrastructure','The public Sites address was observed setting Cloudflare’s technical __cf_bm cookie for protection against automated traffic. According to the provider documentation, it expires after 30 minutes of continuous inactivity. Configuration and behaviour on the final domain must be reviewed before the operational launch.'],['Future changes','Any future non-essential cookie or similar technology will be inventoried and managed through appropriate choices before activation.']]
 },
 cancel: {
  ro: [['Politică în pregătire','Condițiile de anulare și reprogramare vor fi stabilite de cabinet înaintea activării programărilor cu plată. Nu sunt propuse aici termene sau penalități în numele cabinetului.'],['Informații înainte de plată','Versiunea finală va afișa durata consultației, onorariul total aplicabil, fusul orar, formatul întâlnirii, modalitatea confirmării și condițiile de anulare, reprogramare și eventuală rambursare.'],['Situații de reglementat','Cabinetul va preciza procedura și limitele de timp pentru anulare sau reprogramare, neprezentarea, întârzierile, dificultățile tehnice, anularea de către cabinet și tratamentul plăților nereușite ori duplicate.'],['Acceptare și confirmare','Condițiile aprobate vor fi accesibile înaintea plății. Confirmarea unei rezervări reale va depinde de validarea plății și disponibilității, nu doar de selectarea unui interval.'],['În această demonstrație','Nu se efectuează rezervări sau plăți și nu există o operațiune de anulat. Pentru o întâlnire reală, contactați direct cabinetul.']],
  en: [['Policy in preparation','The practice will set cancellation and rescheduling conditions before paid appointments are activated. No deadline or penalty is proposed here on behalf of the practice.'],['Information before payment','The final version will display consultation duration, the applicable total fee, timezone, meeting format, confirmation process and the conditions for cancellation, rescheduling and any refund.'],['Situations to address','The practice will define the procedure and time limits for changes, no-shows, late arrivals, technical difficulties, cancellation by the practice and failed or duplicate payments.'],['Acceptance and confirmation','Approved conditions will be accessible before payment. A real reservation will depend on verification of payment and availability, rather than selection of a slot alone.'],['In this demonstration','No appointment or payment is made, so there is no transaction to cancel. Contact the practice directly for an actual meeting.']]
 },
 accessibility: {
  ro: [['Accesibilitate în proiectare','Structura urmărește navigare cu tastatura, contrast lizibil, titluri ierarhice, etichete pentru controale, legătură de salt la conținut și respectarea preferinței pentru mișcare redusă.'],['Adaptarea afișării','Butonul de accesibilitate din antet permite mărirea textului la 115% sau 130%, activarea contrastului ridicat și resetarea afișării. Preferințele sunt păstrate numai pe dispozitiv. Conținutul se adaptează ecranelor mobile și desktop. Dimensiunile textului folosesc unități relative și paginile sunt pregătite pentru zoom. Calendarul poate fi utilizat prin butoane etichetate, fără gesturi obligatorii.'],['Limite și feedback','Aceasta este o versiune demonstrativă, fără o certificare de accesibilitate. Dacă întâmpinați o dificultate, puteți contacta cabinetul telefonic sau prin e-mail, indicând pagina și natura problemei.']],
  en: [['Accessibility by design','The structure supports keyboard navigation, readable contrast, hierarchical headings, labelled controls, a skip link and reduced-motion preferences.'],['Display adaptation','The accessibility button in the header provides 115% and 130% text sizing, high contrast and display reset. Preferences stay on your device. Content adapts to mobile and desktop screens. Text uses relative units and pages are prepared for zoom. The calendar uses labelled buttons without mandatory gestures.'],['Limits and feedback','This is a demonstration version without accessibility certification. If you encounter a difficulty, contact the practice by phone or email and identify the page and issue.']]
 }
};
function legal(lang,key) { const t=translations[lang]; return `${innerHero(lang,t.legal,t[key],lang==='ro'?'Informații pregătite pentru o experiență clară și responsabilă.':'Information prepared for a clear and responsible experience.')}<section class="section container legal-layout"><article class="prose">${legalContent[key][lang].map(([h,p])=>`<section><h2>${h}</h2><p>${p}</p></section>`).join('')}<p>${lang==='ro'?'Contact cabinet':'Practice contact'}: <a href="mailto:${firm.email}">${firm.email}</a></p></article><aside><h2>${t.legal}</h2>${Object.keys(legalContent).map(k=>`<a class="sidebar-link" href="${url(lang,k)}" ${key===k?'aria-current="page"':''}>${t[k]}${arrow}</a>`).join('')}</aside></section>`; }
function studio(lang) { const en=lang==='en'; return `${innerHero(lang,en?'EDITORIAL STUDIO':'ATELIER EDITORIAL',en?'Your content.<br><em>Your control.</em>':'Conținutul dumneavoastră.<br><em>Controlul dumneavoastră.</em>',en?'A local demonstration of editing and exporting website content.':'O demonstrație locală pentru editarea și exportul conținutului website-ului.')}<section class="section container studio-layout"><div><div class="demo-note"><div><strong>${en?'Local demonstration, not a connected administration panel':'Demonstrație locală, fără un panou de administrare conectat'}</strong><p>${en?'Changes can be previewed and exported. They do not update the published website. Do not enter personal data or case information. A secured CMS and account ownership will be configured separately for handover.':'Modificările pot fi previzualizate și exportate. Nu actualizează site-ul publicat. Nu introduceți date personale sau informații din dosare. Un CMS securizat și titularii conturilor vor fi configurați separat pentru predare.'}</p></div></div><form id="editor-form"><label>${en?'Homepage headline':'Titlul paginii principale'}<input name="headline" maxlength="120" value="${en?'Legal rigour. Clarity in decisions.':'Rigoare juridică. Claritate în decizii.'}" required></label><label>${en?'Introductory text':'Text de introducere'}<textarea name="intro" rows="4" maxlength="700">${translations[lang].heroText}</textarea></label><label>${en?'Article title':'Titlu articol'}<input name="articleTitle" maxlength="180" value="${esc(articles[0][lang].title)}"></label><label>${en?'Article text':'Text articol'}<textarea name="articleBody" rows="6" maxlength="10000">${articles[0][lang].sections[0][1]}</textarea></label><label>${en?'Consultation fee · draft only (RON)':'Onorariu consultație · doar ciornă (RON)'}<input name="fee" type="number" min="0" max="100000" step="0.01" placeholder="${en?'Set by the practice':'Stabilit de cabinet'}"></label><label>${en?'Illustrative image · stays on your device':'Imagine ilustrativă · rămâne pe dispozitiv'}<input id="editor-image" type="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><div class="editor-actions"><button type="submit" class="button gold">${en?'Preview':'Previzualizați'}${arrow}</button><button type="button" id="save-draft" class="button outline">${en?'Save locally':'Salvați local'}</button><button type="button" id="export-draft" class="button outline">${en?'Export JSON':'Exportați JSON'}</button><button type="button" id="clear-draft" class="text-link">${en?'Clear local draft':'Ștergeți ciorna locală'}</button></div><p id="editor-status" role="status"></p></form></div><aside class="editor-preview"><p class="eyebrow">${en?'LOCAL PREVIEW':'PREVIZUALIZARE LOCALĂ'}</p><div id="editor-preview-content"></div><img id="editor-preview-image" alt="${en?'Local image preview':'Previzualizare imagine locală'}" hidden></aside></section>`; }

const pages = [];
for (const lang of ['ro','en']) {
 const t=translations[lang];
 pages.push({lang,key:'home',title:`${firm.name} · ${t.office} ${lang==='ro'?'București':'Bucharest'}`,description:t.heroText,body:home(lang)});
 pages.push({lang,key:'about',title:`${t.nav[1]} · ${firm.name}`,description:t.aboutText2,body:about(lang)});
 pages.push({lang,key:'practices',title:`${t.nav[2]} · ${firm.name}`,description:t.practiceText,body:`${innerHero(lang,t.nav[2],lang==='ro'?'Rigoare juridică.<br><em>O perspectivă completă.</em>':'Legal rigour.<br><em>A considered perspective.</em>',t.practiceText,true)}<section class="section container">${practiceCards(lang)}</section>${cta(lang)}`});
 for (const item of practices) pages.push({lang,key:'practice',item,title:`${item[lang].title} · ${firm.name}`,description:item[lang].lead,body:practice(lang,item)});
 pages.push({lang,key:'booking',title:`${t.nav[3]} · ${firm.name}`,description:lang==='ro'?'Descoperiți experiența de programare a unei consultații. Modul demonstrativ, fără rezervări sau plăți.':'Explore the consultation booking journey. Demonstration only, without reservations or payments.',body:booking(lang)});
 pages.push({lang,key:'articles',title:`${t.nav[4]} · ${firm.name}`,description:lang==='ro'?'Repere practice pentru pregătirea unei consultații și înțelegerea unei situații juridice.':'Practical pointers for preparing a consultation and understanding a legal matter.',body:`${innerHero(lang,t.nav[4],t.articleTitle,lang==='ro'?'Repere practice pentru o discuție mai informată. Materialele sunt generale și nu înlocuiesc analiza situației dumneavoastră.':'Practical pointers for a better-informed conversation. These general materials do not replace an assessment of your situation.')}<section class="section container">${articleCards(lang)}<p class="fineprint editorial-note">${lang==='ro'?'Conținut editorial demonstrativ, pregătit pentru revizia cabinetului înaintea lansării finale.':'Demonstration editorial content, prepared for the practice’s review before the final launch.'}</p></section>`});
 for (const item of articles) pages.push({lang,key:'article',item,title:`${item[lang].title} · ${firm.name}`,description:item[lang].excerpt,body:`${innerHero(lang,item.category[lang==='en'?1:0],item[lang].title,item[lang].excerpt)}<section class="section container article-layout"><article class="prose"><p class="article-meta">${t.articleLabel} · ${lang==='ro'?'Conținut demonstrativ pentru revizia cabinetului':'Demonstration content for review by the practice'}</p>${photo(item.image,'article-cover')}${item[lang].sections.map(([h,p])=>`<section><h2>${h}</h2><p>${p}</p></section>`).join('')}<p class="fineprint">${t.disclaimer}</p><a class="text-link" href="${url(lang,'articles')}">← ${t.articleLink}</a></article></section>${cta(lang)}`});
 pages.push({lang,key:'contact',title:`${lang==='en'?'Contact the practice':t.contact} · ${firm.name}`,description:lang==='ro'?`Contactați cabinetul Manuela Galuscan, București, România. Telefon ${firm.phoneLabel}. Reprezentare în întreaga Românie.`:`Contact Manuela Galuscan’s practice, Bucharest, Romania. Phone ${firm.phoneLabel}.`,body:contact(lang)});
 for (const key of Object.keys(legalContent)) pages.push({lang,key,title:`${t[key]} · ${firm.name}`,description:t[key],body:legal(lang,key)});
 pages.push({lang,key:'studio',title:`${lang==='ro'?'Atelier editorial':'Editorial studio'} · ${firm.name}`,description:lang==='ro'?'Demonstrație locală de administrare a conținutului.':'Local content editing demonstration.',body:studio(lang)});
}
for (const page of pages) {
 const { lang,key,item,title,description,body }=page;
 const path=url(lang,key,item);
 const schema={ '@context':'https://schema.org','@type':'WebPage',name:title,description,url:firm.origin+path,inLanguage:lang,isPartOf:{'@type':'WebSite',name:`${firm.name} · ${translations[lang].office}`,url:firm.origin}};
 const office={'@type':'LegalService','@id':firm.origin+'/#cabinet',name:(lang==='ro'?'Cabinet de Avocatură ':'Law Office ')+firm.name,url:firm.origin,telephone:firm.phone,email:firm.email,address:{'@type':'PostalAddress',addressLocality:lang==='ro'?'București':'Bucharest',addressCountry:'RO'},areaServed:{'@type':'Country',name:'Romania'}};
 if(key==='home')schema.mainEntity=office;
 if(key==='practice')schema.mainEntity={'@type':'Service',name:item[lang].title,serviceType:item[lang].title,provider:office,areaServed:{'@type':'Country',name:'Romania'}};
 const html=`<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="object-src 'none'; base-uri 'self'; form-action 'none'"><meta name="color-scheme" content="light"><meta name="theme-color" content="#14262b"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="noindex, follow"><link rel="canonical" href="${firm.origin+path}"><link rel="alternate" hreflang="ro" href="${firm.origin+url('ro',key,item)}"><link rel="alternate" hreflang="en" href="${firm.origin+url('en',key,item)}"><link rel="alternate" hreflang="x-default" href="${firm.origin+url('ro',key,item)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><meta property="og:type" content="${key==='article'?'article':'website'}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${firm.origin+path}"><meta property="og:image" content="${firm.origin}/assets/social-card-v2.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:locale" content="${lang==='ro'?'ro_RO':'en_GB'}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${firm.origin}/assets/social-card-v2.jpg"><link rel="stylesheet" href="/assets/fonts-v2/editorial.css"><link rel="stylesheet" href="/assets/fonts-v2/sans.css"><link rel="stylesheet" href="/styles.css?v=${version}"><script type="application/ld+json">${JSON.stringify(schema).replaceAll('<','\\u003c')}</script><script src="/app.js?v=${version}" defer></script></head><body id="top" data-page="${key}">${header(lang,key,item)}<main id="main">${body}</main>${footer(lang)}</body></html>`;
 await mkdir(`dist${path}`,{recursive:true});
 await writeFile(`dist${path}index.html`,html);
 page.path=path;
}
await writeFile('dist/404.html',`<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pagina nu a fost găsită · ${firm.name}</title><meta name="robots" content="noindex"><link rel="stylesheet" href="/styles.css?v=${version}"></head><body><main class="container section not-found"><p class="eyebrow">404</p><h1>Această pagină<br>nu a fost găsită.</h1><p>Reveniți la pagina principală sau contactați cabinetul.</p>${button('/','Pagina principală')}${button('/en/','English version','outline')}</main></body></html>`);
await writeFile('dist/robots.txt',`User-agent: *\nAllow: /\n# Public visual concept; every page carries noindex until final approval.\nSitemap: ${firm.origin}/sitemap.xml\n`);
await writeFile('dist/sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.filter(p=>p.key!=='studio').map(p=>`<url><loc>${firm.origin+p.path}</loc></url>`).join('')}</urlset>`);
await writeFile('dist/_headers',`/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=()\n  Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' blob: data:; font-src 'self'; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'self'; form-action 'none'; frame-ancestors 'none'\n  X-Robots-Tag: noindex, follow\n/assets/*\n  Cache-Control: public, max-age=86400\n`);
await writeFile('dist/route-manifest.json',JSON.stringify(pages.map(({path,key,lang})=>({path,key,lang})),null,2));
console.log(`Built ${pages.length} complete bilingual pages + 404. Assets fingerprint: ${version}`);
